import React, { useState, useEffect } from "react";
import axios from "axios";
import ResumeForm from "./components/ResumeForm";
import ResumePreview from "./components/ResumePreview";
import ATSPanel from "./components/ATSPanel";

function App() {
  const [data, setData] = useState({
    name: "",
    email: "",
    summary: "",
    skills: "",
  });

  const [jobDesc, setJobDesc] = useState("");
  const [isPro, setIsPro] = useState(false);

  // 🔥 Load PRO status
  useEffect(() => {
    const saved = localStorage.getItem("isPro");
    if (saved === "true") setIsPro(true);
  }, []);

  // 🔥 Stripe
  const handleSubscribe = async () => {
    try {
      const res = await axios.post("http://localhost:5000/api/checkout");
      window.location.href = res.data.url;
    } catch (err) {
      console.error(err);
      alert("Payment failed");
    }
  };

  // 🔥 Demo mode
  const handleDemoUpgrade = () => {
    localStorage.setItem("isPro", "true");
    setIsPro(true);
    alert("🎉 You are now Pro (Demo Mode)");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white">

      {/* 🔥 NAVBAR */}
      <div className="flex justify-between items-center px-6 py-4 border-b border-gray-700">
        <h1 className="text-2xl font-bold">🚀 CareerForge Pro</h1>

        <div className="flex gap-3 items-center">

  {isPro && (
    <span className="bg-green-600 px-4 py-1 rounded-full text-sm">
      ✅ Pro
    </span>
  )}

  <button
    onClick={handleSubscribe}
    className="bg-gradient-to-r from-purple-500 to-pink-500 px-4 py-2 rounded-lg"
  >
    {isPro ? "Manage Plan" : "Upgrade"}
  </button>

</div>
      </div>

      {/* 🔥 MAIN CONTENT */}
      <div className="max-w-6xl mx-auto px-4 py-6 space-y-6">

        {/* Resume Builder */}
        <div className="bg-white/10 backdrop-blur-md p-6 rounded-2xl shadow-lg hover:shadow-xl hover:scale-[1.02] transition duration-300">
          <h2 className="text-xl font-semibold mb-4">📄 Resume Builder</h2>
          <ResumeForm data={data} setData={setData} />
        </div>

        {/* Preview */}
        <div className="bg-white/10 backdrop-blur-md p-6 rounded-2xl shadow-lg hover:shadow-xl hover:scale-[1.02] transition duration-300">
          <h2 className="text-xl font-semibold mb-4">👀 Live Preview</h2>
          <ResumePreview data={data} isPro={isPro} />
        </div>

        {/* ATS + AI */}
        <div className="bg-white/10 backdrop-blur-md p-6 rounded-2xl shadow-lg hover:shadow-xl hover:scale-[1.02] transition duration-300">
          <h2 className="text-xl font-semibold mb-4">🤖 ATS + AI Tools</h2>
          <ATSPanel
            data={data}
            jobDesc={jobDesc}
            setJobDesc={setJobDesc}
            isPro={isPro}
          />
        </div>

      </div>

      {/* 🔥 UPGRADE SECTION (BOTTOM) */}
      {!isPro && (
        <div className="text-center py-10 space-y-3">
          <button
            onClick={handleSubscribe}
            className="bg-gradient-to-r from-purple-500 to-pink-500 px-6 py-3 rounded-lg font-semibold hover:scale-105 transition"
          >
            💳 Upgrade to Pro ($5/month)
          </button>

          <button
            onClick={handleDemoUpgrade}
            className="text-sm text-gray-400 underline"
          >
            Use Demo Mode (Skip Payment)
          </button>
        </div>
      )}

    </div>
  );
}

export default App;
